import torch
import torch.nn as nn
from cutegen.ptx_runtime import PtxModule, i32, u32, i64, u64, f32, f64

PTX_SOURCE = r"""
.version 7.8
.target sm_89
.address_size 64

.visible .entry sigmoid_kernel(
    .param .u64 in_ptr,
    .param .u64 out_ptr,
    .param .u32 n
)
{
    .reg .u32 %r_tid, %r_ctaid, %r_ntid, %r_idx, %r_n;
    .reg .u64 %rd_in, %rd_out, %rd_off, %rd_a, %rd_b;
    .reg .f32 %f_val, %f_neg, %f_scaled, %f_exp, %f_one, %f_sum, %f_res;
    .reg .pred %p_oob;

    ld.param.u64 %rd_in, [in_ptr];
    ld.param.u64 %rd_out, [out_ptr];
    ld.param.u32 %r_n, [n];

    cvta.to.global.u64 %rd_in, %rd_in;
    cvta.to.global.u64 %rd_out, %rd_out;

    mov.u32 %r_tid, %tid.x;
    mov.u32 %r_ctaid, %ctaid.x;
    mov.u32 %r_ntid, %ntid.x;
    mad.lo.u32 %r_idx, %r_ctaid, %r_ntid, %r_tid;

    setp.ge.u32 %p_oob, %r_idx, %r_n;
    @%p_oob bra DONE;

    mul.wide.u32 %rd_off, %r_idx, 4;
    add.u64 %rd_a, %rd_in, %rd_off;
    add.u64 %rd_b, %rd_out, %rd_off;

    ld.global.f32 %f_val, [%rd_a];

    neg.f32 %f_neg, %f_val;
    mul.f32 %f_scaled, %f_neg, 0f3FB8AA3B;
    ex2.approx.f32 %f_exp, %f_scaled;
    mov.f32 %f_one, 0f3F800000;
    add.f32 %f_sum, %f_one, %f_exp;
    rcp.approx.f32 %f_res, %f_sum;

    st.global.f32 [%rd_b], %f_res;

DONE:
    ret;
}
"""

_ptx_module = None

def _get_ptx_module():
    global _ptx_module
    if _ptx_module is None:
        _ptx_module = PtxModule(PTX_SOURCE)
    return _ptx_module

def validate_generated_code():
    # Force PTX JIT assembly and entry-point lookup during compile validation.
    _get_ptx_module().function("sigmoid_kernel")

class ModelNew(nn.Module):
    def __init__(self):
        super().__init__()

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        assert x.is_cuda, "Input tensor must be on CUDA device"
        x_contig = x.contiguous()
        out = torch.empty_like(x_contig)

        n = x_contig.numel()
        module = _get_ptx_module()

        block_x = 256
        grid_x = (n + block_x - 1) // block_x

        module.launch(
            "sigmoid_kernel",
            grid=(grid_x, 1, 1),
            block=(block_x, 1, 1),
            arguments=[x_contig, out, i32(n)],
            shared_memory=0,
            stream=torch.cuda.current_stream(x.device),
        )

        return out.view_as(x)

